// @ts-check
// Writes ios/App/flavour.xcconfig (gitignored) from the flavour table, so the Xcode
// target's bundle id and display name follow FLAVOUR (AD-18). Run by `cap:sync`
// before `cap sync`. ios/flavour-base.xcconfig includes the generated file with
// `#include?` and falls back to the dev values when it is missing.
//
// Usage: FLAVOUR=playtest node scripts/write-ios-flavour.mjs   (unset means dev)

import { realpathSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { resolveFlavour } from '../flavours.ts';

const clientDir = join(dirname(fileURLToPath(import.meta.url)), '..');

/** Path of the generated xcconfig. */
export const IOS_FLAVOUR_XCCONFIG = join(clientDir, 'ios', 'App', 'flavour.xcconfig');

/**
 * The xcconfig text for a flavour.
 * @param {import('../flavours.ts').Flavour} flavour
 * @returns {string}
 */
export function xcconfigFor(flavour) {
  for (const value of [flavour.appId, flavour.appName]) {
    // xcconfig has no quoting: a newline or `//` would corrupt or truncate the value.
    if (/[\r\n]|\/\//.test(value)) throw new Error(`Flavour value not representable in xcconfig: ${value}`);
  }
  return [
    '// Generated by apps/client/scripts/write-ios-flavour.mjs from apps/client/flavours.ts. Do not edit.',
    `// FLAVOUR=${flavour.name}`,
    `NUMCEPTION_FLAVOUR = ${flavour.name}`,
    `NUMCEPTION_APP_ID = ${flavour.appId}`,
    `NUMCEPTION_APP_NAME = ${flavour.appName}`,
    '',
  ].join('\n');
}

function main() {
  const flavour = resolveFlavour(process.env);
  writeFileSync(IOS_FLAVOUR_XCCONFIG, xcconfigFor(flavour));
  console.log(`✔ ios/App/flavour.xcconfig: ${flavour.name} (${flavour.appId}, "${flavour.appName}")`);
}

/** True when this file is the entry point, even if invoked through a symlink. */
function isEntryPoint() {
  const entry = process.argv[1];
  if (!entry) return false;
  try {
    return realpathSync(fileURLToPath(import.meta.url)) === realpathSync(entry);
  } catch {
    return false;
  }
}

if (isEntryPoint()) {
  try {
    main();
  } catch (e) {
    console.error(`write-ios-flavour: ${e instanceof Error ? e.message : String(e)}`);
    process.exit(1);
  }
}
